contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint amount) public {
        require(amount > address(c).balance);
        uint dcBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore && c.depositsCount() == dcBefore);
    }
    receive() external payable {}
}

